import{u as S,c as v,d,m as h,e,h as n,_ as k,t as s,i as c,F as b,j as y,w as T,n as x,k as p,N as C}from"./BdDiYQ8m.js";import{b as M}from"./BgwgXOtT.js";import{_ as A}from"./BPZIIl5-.js";import{u as P}from"./DQUj6XJn.js";const L={class:"bg-orange-500 text-white p-4 sm:p-6 pt-24 sm:pt-28 md:pt-32 pb-8 sm:pb-10 border-b-3 border-black"},I={class:"max-w-7xl mx-auto text-center relative lg:px-4"},D={class:"relative w-16 h-16 mx-auto mb-5"},F={class:"relative bg-black text-white rounded-lg p-3 flexx transform -rotate-3 hover:rotate-0 transition-transform duration-300"},j={class:"text-3xl sm:text-4xl font-black uppercase tracking-tight mb-1"},R={class:"text-white"},H={class:"text-black text-xl sm:text-2xl font-black uppercase tracking-tight mb-3 flex items-center justify-center gap-2 flex-wrap"},O={class:"text-white/90 font-bold mb-4 max-w-2xl mx-auto text-sm sm:text-base px-2 sm:px-0"},N={class:"flex items-center justify-center flex-wrap gap-3 text-xs mb-5"},E={class:"flex items-center gap-1.5 text-white/80"},q=["datetime"],U={class:"text-white/90 font-bold"},G={class:"flex items-center justify-center flex-wrap gap-2","aria-label":"Claude video guides"},ae={__name:"ClaudeVideoHeader",props:{icon:{type:String,required:!0},title:{type:String,required:!0},subtitle:{type:String,required:!0},tagline:{type:String,required:!0},lastUpdated:{type:String,default:""},stats:{type:Array,default:()=>[]}},setup(a){const m=[{to:"/claude-video",label:"Video guide",icon:"ph:film-strip-bold"},{to:"/opus-video-prompts",label:"Prompt builder",icon:"ph:magic-wand-bold"},{to:"/claude-motion-graphics",label:"Motion graphics styles",icon:"ph:shapes-bold"}],i=a,f=S(),u=v(()=>{const l=new Date(i.lastUpdated);return Number.isNaN(l.getTime())?i.lastUpdated:l.toLocaleDateString("en-US",{month:"short",day:"numeric",year:"numeric"})});return(l,t)=>{const r=k,g=M,w=A;return h(),d("header",L,[t[4]||(t[4]=e("a",{href:"#main-content",class:"sr-only focus:not-sr-only focus:absolute focus:top-4 focus:left-4 bg-orange-600 text-white px-4 py-2 rounded z-50"},"Skip to main content",-1)),e("div",I,[e("div",D,[t[0]||(t[0]=e("div",{class:"absolute inset-0 bg-white rounded-lg transform rotate-3 opacity-80"},null,-1)),e("div",F,[n(r,{name:a.icon,size:"26"},null,8,["name"])])]),e("h1",j,[e("span",R,s(a.title),1)]),e("p",H,[c(s(a.subtitle)+" ",1),t[1]||(t[1]=e("span",{class:"align-middle text-xs font-black text-orange-500 bg-white border-2 border-black px-2 py-0.5 rounded"},"Opus 5.5",-1))]),e("p",O,[n(g,{text:a.tagline,"mark-class":"bg-black text-white px-1"},null,8,["text"])]),e("div",N,[e("span",E,[n(r,{name:"ph:arrows-clockwise-bold",size:"14"}),t[2]||(t[2]=c(" Updated ",-1)),e("time",{datetime:a.lastUpdated},s(u.value),9,q)]),(h(!0),d(b,null,y(a.stats,o=>(h(),d(b,{key:o},[t[3]||(t[3]=e("span",{class:"text-white/40"},"•",-1)),e("span",U,s(o),1)],64))),128))]),e("nav",G,[(h(),d(b,null,y(m,o=>n(w,{key:o.to,to:o.to,class:x(["flex items-center gap-1.5 px-3 py-1.5 rounded-full text-xs font-bold border transition-colors",p(f).path===o.to?"bg-white text-orange-600 border-white":"bg-transparent text-white border-white/40 hover:bg-white/10"])},{default:T(()=>[n(r,{name:o.icon,size:"14"},null,8,["name"]),c(" "+s(o.label),1)]),_:2},1032,["to","class"])),64))])])])}}},W={class:"border-2 border-black bg-white flex flex-col"},_={class:"p-3 flex items-start justify-between gap-2 border-b border-gray-200"},B={class:"min-w-0"},V={class:"text-sm font-black"},z=["aria-label"],$=["innerHTML"],oe={__name:"PromptBox",props:{title:{type:String,required:!0},prompt:{type:String,required:!0},scroll:{type:Boolean,default:!1}},setup(a){const m=a,{copied:i,copy:f}=P(),u=t=>t.replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;"),l=v(()=>u(m.prompt).replace(/\[([^\]]+)\]/g,'<mark class="bg-orange-100 text-orange-700 font-bold rounded px-0.5">[$1]</mark>'));return(t,r)=>{const g=k;return h(),d("article",W,[e("div",_,[e("div",B,[e("h3",V,s(a.title),1),C(t.$slots,"default")]),e("button",{type:"button",class:"shrink-0 flex items-center gap-1.5 bg-orange-500 hover:bg-orange-600 text-white border-2 border-black rounded px-2.5 py-1 text-xs font-black transition-colors","aria-label":`Copy prompt: ${a.title}`,onClick:r[0]||(r[0]=w=>p(f)(a.prompt,"prompt"))},[n(g,{name:p(i)?"ph:check-bold":"ph:copy-bold",size:"13"},null,8,["name"]),c(" "+s(p(i)?"Copied":"Copy"),1)],8,z)]),e("pre",{class:x(["flex-1 p-3 text-[11.5px] leading-relaxed font-mono whitespace-pre-wrap break-words text-gray-800 bg-gray-50",a.scroll&&"max-h-[480px] overflow-auto"]),innerHTML:l.value},null,10,$)])}}},Y={lastUpdated:"2026-10-21",corpus:{prompts:703,fullPrompts:496,authors:616}},K=JSON.parse(`{"pipeline":[{"id":"brief","title":"Write the brief","icon":"ph:note-pencil-bold","body":"Say what the viewer should understand, how long it runs, and where it will play. Duration is the one spec nearly everyone gives. [[Aspect ratio is the one most people forget]], and it decides the whole layout."},{"id":"storyboard","title":"Get a storyboard first","icon":"ph:squares-four-bold","body":"Ask for a shot list with timestamps before any code. [[Fixing a line in a storyboard costs one message.]] Fixing a finished scene costs a rewrite."},{"id":"code","title":"Claude writes the scene as code","icon":"ph:code-bold","body":"Usually one HTML file with Canvas, SVG, Three.js or shaders. The rule that makes export work: [[every frame is a pure function of time]], so render(t) always draws the same picture for the same t."},{"id":"review","title":"Review stills, not the live preview","icon":"ph:images-bold","body":"Have Claude render a contact sheet, one frame per beat or per second, and look at it. In Claude Code it can [[read the PNGs itself and fix what it sees]] before you spend minutes on a full render."},{"id":"render","title":"Render frame by frame to MP4","icon":"ph:film-reel-bold","body":"A headless browser steps time one frame at a time, screenshots each frame and pipes it to ffmpeg. [[No dropped frames, any resolution]], and the audio track is muxed in at the end instead of recorded."}],"stacks":[{"id":"canvas","name":"Canvas 2D","share":38,"bestFor":"Motion graphics, kinetic type, particles, charts, explainers","look":"Flat, crisp, fast to render","note":"The default Claude reaches for. Easy to make deterministic because you redraw the whole frame from t."},{"id":"svg","name":"SVG + GSAP","share":26,"bestFor":"Logo reveals, UI animation, line drawing, icon systems","look":"Vector-sharp at any resolution","note":"GSAP timelines can be seeked: build the timeline paused and call timeline.seek(t) per frame."},{"id":"threejs","name":"Three.js / WebGL","share":19,"bestFor":"3D worlds, product turntables, flythroughs, games","look":"Real depth, lighting, camera moves","note":"Needs a GPU-backed headless browser for speed. Read pixels back after each render, not from a realtime loop."},{"id":"shader","name":"GLSL shaders","share":13,"bestFor":"Abstract loops, backgrounds, fluid and light effects","look":"Dense, organic, generative","note":"Already a function of a time uniform. Pass t in and it exports cleanly."},{"id":"p5brush","name":"p5.js + p5.brush","share":null,"bestFor":"Hand-painted cartoons, watercolour, storybook shorts","look":"Brush strokes, paper texture, boiling linework","note":"Slow without a GPU (seconds per frame). Plain p5 shapes look like 2000s Flash; paint everything with brushes."},{"id":"remotion","name":"Remotion / HyperFrames","share":null,"bestFor":"Long promos, multi-scene films, React teams","look":"Whatever you build in React or HTML","note":"Frameworks that already give you frame-based time and a renderer. Worth it past about a minute of video."}],"determinismRules":[{"rule":"Read time, never count frames","detail":"Position = f(t). A variable that increments every frame breaks the moment frames render out of order or in parallel."},{"rule":"Seed every random number","detail":"Math.random() gives different noise on every render. Use a hash of the index or a seeded generator so frame 212 is always frame 212."},{"rule":"No physics that integrates step by step","detail":"Simulations that add velocity each tick drift. Precompute them once, or use closed-form motion."},{"rule":"Wait for fonts before frame 0","detail":"await document.fonts.ready, or the first frames render in a fallback font."},{"rule":"Let ffmpeg add the audio","detail":"Never record sound from the browser. Mux the original track into the MP4 at the end, so sync is exact."},{"rule":"Tag colour as BT.709","detail":"Untagged HD video gets decoded with the wrong matrix on some players, shifting colours. Ask for the BT.709 fix below."}],"renderScript":"// Render any HTML animation to MP4, frame by frame, with a virtual clock.\\n// npm i playwright-core  (uses your installed Chrome; needs ffmpeg on PATH)\\n// node claude-video-render.mjs scene.html out.mp4 [seconds=6] [fps=60] [width=1920] [height=1080]\\nimport { chromium } from 'playwright-core'\\nimport { spawn } from 'node:child_process'\\nimport { pathToFileURL } from 'node:url'\\nimport { resolve } from 'node:path'\\n\\nconst [input, output = 'out.mp4', seconds = '6', fps = '60', width = '1920', height = '1080'] = process.argv.slice(2)\\nconst frameCount = Math.round(Number(seconds) * Number(fps))\\nconst frameMs = 1000 / Number(fps)\\n\\nconst virtualClock = () => {\\n  let now = 0\\n  let queue = []\\n  const startDate = Date.now()\\n  performance.now = () => now\\n  Date.now = () => startDate + now\\n  window.requestAnimationFrame = (cb) => queue.push(cb)\\n  window.cancelAnimationFrame = () => {}\\n  window.__advance = (ms) => {\\n    now += ms\\n    const callbacks = queue\\n    queue = []\\n    callbacks.forEach((cb) => cb(now))\\n    document.getAnimations().forEach((a) => { a.pause(); a.currentTime = now })\\n  }\\n}\\n\\nconst browser = await chromium.launch({ channel: 'chrome' })\\nconst page = await browser.newPage({ viewport: { width: Number(width), height: Number(height) } })\\nawait page.addInitScript(virtualClock)\\nconst url = input.startsWith('http') ? input : pathToFileURL(resolve(input)).href\\nawait page.goto(url, { waitUntil: 'networkidle' })\\nawait page.evaluate(() => document.fonts.ready)\\n\\nconst ffmpeg = spawn('ffmpeg', ['-y', '-f', 'image2pipe', '-framerate', fps, '-i', '-',\\n  '-c:v', 'libx264', '-pix_fmt', 'yuv420p', '-crf', '18', '-movflags', '+faststart', output], { stdio: ['pipe', 'inherit', 'inherit'] })\\n\\nfor (let i = 0; i < frameCount; i++) {\\n  await page.evaluate((ms) => window.__advance(ms), i === 0 ? 0 : frameMs)\\n  ffmpeg.stdin.write(await page.screenshot({ type: 'png' }))\\n  if (i % Number(fps) === 0) console.log(\`frame \${i}/\${frameCount}\`)\\n}\\nffmpeg.stdin.end()\\nawait new Promise((done) => ffmpeg.on('close', done))\\nawait browser.close()\\nconsole.log(\`wrote \${output}\`)\\n","renderPrompt":"Render [scene.html] to an MP4 with the frame-by-frame script at https://awesomeclaude.ai/claude-video-render.mjs.\\n- Size and length: [1920x1080], [60] fps, [15] seconds.\\n- Install playwright-core if it is missing. Use the Chrome and ffmpeg already on this machine.\\n- If the animation counts frames, calls Math.random() or steps physics forward each tick, fix that first so every frame is a pure function of time.\\n- After the render, make a contact sheet with one frame per second and look at it. List any frame where text overlaps, gets cut off or the screen is empty, fix those and render again.","finishPrompts":[{"id":"audio","title":"Add a music track","prompt":"Add [track.mp3] to out.mp4 as the soundtrack. Copy the video stream without re-encoding, encode the audio as AAC 192k, and end at whichever is shorter."},{"id":"bt709","title":"Keep colours right on YouTube","prompt":"Re-encode out.mp4 for YouTube: tag primaries, transfer and matrix as BT.709, H.264 at CRF 18, yuv420p, so the colours match the browser."},{"id":"vertical","title":"Vertical 9:16 for Reels, Shorts, TikTok","prompt":"Make a vertical 1080x1920, 30fps version for Reels and Shorts. Move titles and captions out of the top and bottom 15% first, then render it."},{"id":"gif","title":"Small looping GIF for a README","prompt":"Turn out.mp4 into a looping GIF for a README: 640px wide, 15fps, with a generated palette so it stays small and sharp."},{"id":"blur","title":"Cheap motion blur","prompt":"Add motion blur: render the scene at 240fps, then blend every 4 frames down to a 60fps H.264 MP4."},{"id":"sheet","title":"Contact sheet for review","prompt":"Make a contact sheet of out.mp4, one frame per second in a 4x3 grid. Look at it and tell me what to fix before the final render."}],"routes":[{"id":"chat","title":"claude.ai chat","icon":"ph:chat-circle-text-bold","fit":"Fastest way to see something move","steps":["Paste a prompt and ask for a single HTML file","It plays in the chat as an artifact","Screen-record it, or download the HTML and render it with the script below"],"limits":"Screen recording drops frames and caps you at your screen resolution. No audio muxing, no self-review."},{"id":"code","title":"Claude Code","icon":"ph:terminal-window-bold","fit":"Real MP4s, audio, multi-scene projects","steps":["Empty folder, Opus 5.5, effort high or xhigh","Claude writes the scene, the render script and runs both","It reads its own contact sheets and fixes problems before the final render"],"limits":"Needs Node.js, Chrome and ffmpeg on your machine. Long films can take a big share of a weekly allowance."},{"id":"skill","title":"A style skill","icon":"ph:puzzle-piece-bold","fit":"Same look every time, less prompting","steps":["Drop a SKILL.md with your style rules into .claude/skills/","Say \\"make a 15s launch video in the swiss grid style\\"","Claude loads the style, asks for missing facts, then builds"],"limits":"Only as good as the rules in it.","link":{"to":"/claude-motion-graphics#skill","label":"Start from our free Claude motion graphics skill"}}],"reportedCosts":[{"what":"15s launch spot from a one-line prompt","time":"~1 min","cost":"~$2 API"},{"what":"Promo built with Remotion","time":"~10 min","cost":"not stated"},{"what":"5 min explainer with TTS and subtitles","time":"26 min","cost":"\\"very low tokens\\""},{"what":"3 min history film, ~7,400 lines","time":"~1 h","cost":"7% of a weekly quota"},{"what":"Hand-painted music video, 156s, two generations","time":"not stated","cost":"10% of a Max 5x week"},{"what":"Lyric music video at xhigh effort","time":"45 min first cut","cost":"~$200 API"},{"what":"Full song as 4K60 three.js MV, render only","time":"~57 min on an M5 Pro","cost":"local"}],"lessons":[{"title":"Short prompts work","body":"Almost half of the 496 full prompts we analysed are under 200 characters. [[Claude picks the stack itself]]: only 38% name a library."},{"title":"Ask for a storyboard before code","body":"The best-produced pieces all [[start with a shot list on a beat grid]]. Edit single shots after, one change per message."},{"title":"Count the reads, not the seconds","body":"Claude knows what happens because it wrote the code. The viewer does not. List each thing the viewer must understand and [[give each one its own time slot]]."},{"title":"Ban the template look","body":"Particle bursts, lens flares, neon glow, RGB split and bouncy easing are what make AI motion look like AI motion. [[Name them as off-limits.]]"},{"title":"Let it watch its own work","body":"Only 7% of prompts ask Claude to check frames, but [[nearly every high-end result did]]. Contact sheets catch overlapping text and dead time."},{"title":"Bring the music and the facts","body":"Generated music gets the most complaints. [[Supply a licensed track and its BPM.]] For explainers, check every number yourself."},{"title":"Effort level shows on screen","body":"Creators report that higher reasoning effort makes scenes more detailed and more extravagant. [[Use high or xhigh for a final piece.]]"},{"title":"Budget for rounds","body":"A \\"one-shot\\" result usually took two or more rounds. Plan for [[a draft at half resolution]], notes, then the final render."}],"faqs":[{"q":"Can Claude generate video?","a":"Not directly. Claude Opus 5.5 takes text and images in and writes text out, so it has no video model. What it does very well is write code that draws every frame (Canvas, SVG, Three.js, shaders). A headless browser renders that code frame by frame and ffmpeg turns the frames into an MP4."},{"q":"How do I export an MP4 from a Claude animation?","a":"Two ways. Quick: play the HTML in a browser and screen-record it. Proper: render it frame by frame. Paste the render prompt on this page into Claude Code, or run our free script yourself. It loads the HTML in headless Chrome, replaces the clock so time advances exactly 1/60 s per frame, screenshots every frame and pipes them into ffmpeg. You need Node.js, Chrome and ffmpeg."},{"q":"Do I need Claude Code, or does claude.ai work?","a":"claude.ai works for previews: ask for a single HTML file and it plays in the chat. Claude Code is better for finished videos because it can run the renderer, add audio, read its own contact sheets and fix what it sees."},{"q":"Is making videos with Opus 5.5 free?","a":"The rendering is free and runs on your machine. The model time is not. Creators report anything from about $2 of API usage for a 15 second clip to around $200 for a full music video, or 5 to 10% of a weekly Pro or Max allowance."},{"q":"What kind of video is Claude good at?","a":"Motion graphics, product launch spots, explainers, kinetic typography, data stories, logo reveals, hand-drawn style cartoons, 3D scenes and game-like pieces. It is weak at photoreal footage of people and places. Creators who need that combine it with a video model."},{"q":"Which aspect ratio and frame rate should I ask for?","a":"Match the platform: 1920x1080 for YouTube and landing pages, 1080x1920 for Reels, Shorts and TikTok, 1080x1080 or 1080x1350 for feeds. 60fps for motion graphics and UI, 24fps for a hand-drawn or filmic look. Only 8% of creator prompts state the aspect ratio, which is why so many clips end up letterboxed."},{"q":"Can Claude add music and voiceover?","a":"Yes, through code. It can synthesize music with Web Audio or Python, and call a TTS service for narration. In practice a licensed track you choose sounds better. Give Claude its BPM so cuts land on the beat, and let ffmpeg mux it in."},{"q":"Should I use Opus or Sonnet for video?","a":"Opus 5.5 for the final piece. Single creator tests found Sonnet close on charts, cards and simple 3D at roughly a quarter to half the cost, and weaker on hand-drawn and ink styles. A common pattern is Opus for the storyboard and review, cheaper models for individual scenes."},{"q":"Why does my exported video flicker or jump?","a":"The animation keeps state between frames: a counter, Math.random(), CSS transitions, or physics that steps forward each tick. When frames render out of order or in parallel that state is wrong. Make every frame a pure function of time and seed all randomness."},{"q":"How long does it take?","a":"A 15 second motion graphic can be a single prompt and a few minutes. A polished one minute piece is usually several rounds over an hour or two. Rendering 4K60 of a full song took one creator about an hour on a fast laptop."}]}`),J=JSON.parse(`{"anatomy":[{"element":"Duration","share":44,"why":"Sets the number of beats. 15s is the most common ask, then 30s and 20s."},{"element":"Music, sound or narration","share":33,"why":"Without it Claude makes a silent piece or synthesizes weak music."},{"element":"Camera language","share":23,"why":"\\"Slow push in\\", \\"whip pan\\", \\"cut on action\\" give it real moves to perform."},{"element":"Things to avoid","share":19,"why":"The fastest way to lose the generic AI look."},{"element":"Style reference","share":19,"why":"One named style beats five adjectives."},{"element":"Export instructions","share":17,"why":"Without them you get a page to watch, not a file."},{"element":"Scene-by-scene beats","share":14,"why":"Controls pacing. Most bad clips are too fast in the middle."},{"element":"Frame rate","share":13,"why":"60 for UI and motion graphics, 24 for drawn or filmic."},{"element":"Aspect ratio","share":8,"why":"Decides layout. The most skipped spec with the biggest effect."},{"element":"Self-review of frames","share":7,"why":"Rare in prompts, common in the best results."}],"formats":[{"id":"launch","label":"Product launch","icon":"ph:rocket-launch-bold","goal":"a launch video for {subject}","beats":["Hook: the problem in one line","The product appears","Three real features, one per beat","Proof: a number or a quote","Name, URL and call to action"]},{"id":"explainer","label":"Explainer","icon":"ph:chalkboard-teacher-bold","goal":"an explainer that teaches {subject}","beats":["The question the viewer has","The core idea as one picture","Step by step, one step per beat","A worked example","The takeaway in one sentence"]},{"id":"logo","label":"Logo reveal","icon":"ph:seal-check-bold","goal":"a logo reveal for {subject}","beats":["Abstract shapes that hint at the mark","Shapes assemble into the logo","Wordmark resolves","Hold on the final frame for one second"]},{"id":"data","label":"Data story","icon":"ph:chart-line-up-bold","goal":"a data story about {subject}","beats":["The headline number, big","The chart builds bar by bar or point by point","One annotation calls out what matters","Source line and conclusion"]},{"id":"lyric","label":"Lyric / kinetic type","icon":"ph:text-aa-bold","goal":"a kinetic typography video for {subject}","beats":["Words enter on the beat","Emphasis words get scale and colour","Layouts change every phrase","Final line holds"]},{"id":"ui","label":"App / UI walkthrough","icon":"ph:app-window-bold","goal":"a UI walkthrough of {subject}","beats":["The empty state","Cursor performs the key action","The interface reacts, zoom on the detail","The result the user gets"]},{"id":"world","label":"3D world","icon":"ph:cube-bold","goal":"a 3D flythrough of {subject}","beats":["Establishing wide shot","Camera pushes into the main area","One moment of life or movement","Pull out to reveal the whole world"]},{"id":"story","label":"Character short","icon":"ph:smiley-bold","goal":"a short animated story about {subject}","beats":["Character wants something","An obstacle","An attempt that fails","A surprise solution","A payoff that rhymes with the opening"]},{"id":"showreel","label":"Showreel / surprise me","icon":"ph:sparkle-bold","goal":"a motion design showreel themed around {subject}","beats":["Open on a bold typographic hit","Rapid style changes, each on a beat","One slower moment to breathe","End on a clean title card"]}],"durations":[10,15,30,60],"aspects":[{"id":"16x9","label":"16:9","size":"1920x1080","for":"YouTube, websites"},{"id":"9x16","label":"9:16","size":"1080x1920","for":"Reels, Shorts, TikTok"},{"id":"1x1","label":"1:1","size":"1080x1080","for":"X, LinkedIn feed"},{"id":"4x5","label":"4:5","size":"1080x1350","for":"Instagram feed"}],"audioOptions":[{"id":"none","label":"Silent","line":"No audio. Make the motion carry the rhythm on an implied 120 BPM grid."},{"id":"track","label":"My music track","line":"I will supply a licensed music track at {bpm} BPM. Put every cut and key hit on the beat grid. ffmpeg will mux the track in, so do not generate audio."},{"id":"synth","label":"Generate music","line":"Synthesize a simple soundtrack in code (Web Audio or a Python script that writes a WAV) and keep cuts on its beat grid."},{"id":"voice","label":"Voiceover","line":"Write a voiceover script first, timed per scene. Leave room for narration, and keep on-screen text shorter than the spoken line."}],"banList":"particle bursts, lens flares, neon glow, RGB split, glitch effects, bouncy elastic easing on everything, gradients as decoration, text that repeats what the picture already shows, and dead time where nothing moves","followUps":[{"phrase":"Slow down the middle section, the viewer cannot read it.","when":"Text flashes by"},{"phrase":"Only the key hits should land on the beat. Everything else can breathe.","when":"It feels frantic"},{"phrase":"Something should happen in every shot. Shot 3 is dead time.","when":"A section stalls"},{"phrase":"Render a contact sheet, one frame per beat, and check it for overlaps before the full render.","when":"Before the final export"},{"phrase":"Keep everything else. Only change scene 2.","when":"A fix broke other scenes"},{"phrase":"Less text. Show it, then label it once.","when":"It looks like a slide deck"},{"phrase":"Use real UI components, not screenshots or a recording.","when":"Product shots look fake"},{"phrase":"Draft at half resolution with no motion blur, then do the final at full quality.","when":"Renders are slow"},{"phrase":"Make the transitions carry motion from one shot into the next.","when":"Cuts feel like slides"},{"phrase":"Now write the render script and export a 1080p60 MP4.","when":"You only have the HTML"}],"templates":[{"id":"saas-launch-15","title":"15-second SaaS launch spot","format":"launch","duration":15,"aspect":"16:9","prompt":"Make a 15-second launch video for [product], which [one sentence on what it does].\\n\\nAudience: [who it is for]. Real features to show, do not invent others: [feature 1], [feature 2], [feature 3].\\n\\nStructure, one beat each: the problem in five words, the product UI appears, the three features, the URL [url].\\nBuild the UI from HTML components in the product's own colours ([hex codes]), not screenshots.\\n1920x1080, 60fps. Every frame must be a pure function of time, render(t).\\nAvoid particle bursts, lens flares, glow and bouncy easing.\\nShow me the storyboard with timestamps first, then build a single HTML file."},{"id":"showreel","title":"The showreel one-liner, done properly","format":"showreel","duration":20,"aspect":"16:9","prompt":"Make a 20-second motion design piece that shows what an excellent motion designer you are, themed around [topic].\\n\\nRules: at least six distinct visual ideas, each on a beat of a 120 BPM grid. One slower moment around second 12 so it can breathe. End on a clean title card that says [text].\\nNo particle bursts, lens flares, glow or RGB split. Flat colour, strong typography.\\nSingle HTML file, 1920x1080, 60fps, every frame computed from t so it can be rendered offline."},{"id":"how-it-works","title":"How-it-works explainer","format":"explainer","duration":45,"aspect":"16:9","prompt":"Make a 45-second explainer of how [concept] works, for [audience].\\n\\nFirst, list the 4 to 6 things a viewer must understand, in order. Give each one its own time slot of at least 5 seconds. Only one new idea on screen at a time.\\nVisual style: clean diagrams that build piece by piece, labels appear only when the part they name appears.\\nWrite a voiceover script timed per scene, then the animation.\\n1920x1080, 30fps, single HTML file, render(t) is deterministic. Double-check every fact and number. If you are unsure, say so instead of drawing it."},{"id":"logo-sting","title":"Logo sting, 6 seconds","format":"logo","duration":6,"aspect":"16:9","prompt":"Here is my logo as SVG: [paste SVG]. Make a 6-second logo reveal.\\n\\nTake the logo apart into its real shapes and animate them assembling. Do not redraw or change the mark. The wordmark resolves last, then hold the final frame for a full second.\\nMotion: confident and quick in, soft settle. One accent colour [hex] on white.\\n1920x1080 and 1080x1080 versions, 60fps, single HTML file per version with render(t)."},{"id":"data-story","title":"Animated chart from real numbers","format":"data","duration":20,"aspect":"1:1","prompt":"Turn this data into a 20-second animated data story: [paste CSV or table].\\n\\nLead with the single most surprising number, big. Then build the chart one series at a time. Add one annotation that says why the change matters. End with the source line \\"[source]\\".\\nUse only the numbers given. Axis labels must be readable on a phone.\\n1080x1080, 60fps, single HTML file, every frame from t. Render a contact sheet of 6 frames and check label overlaps before you finish."},{"id":"vertical-feature","title":"Vertical feature announcement","format":"launch","duration":15,"aspect":"9:16","prompt":"Make a 15-second vertical video (1080x1920) announcing [feature] in [product].\\n\\nThe first second must make sense with the sound off: a big, short headline. Keep everything inside the middle 80% of the frame so platform buttons do not cover it.\\nShow the feature as a real UI interaction: cursor or finger, tap, the result. End on \\"[call to action]\\".\\n30fps, single HTML file, deterministic render(t). No particle effects, no glow."},{"id":"lyric-video","title":"Lyric video synced to a track","format":"lyric","duration":60,"aspect":"16:9","prompt":"Make a kinetic typography lyric video. Track: [song], [BPM] BPM. Here are the lyrics with start times in seconds: [paste lines with timestamps].\\n\\nEach phrase gets its own layout. Emphasis words get scale or colour, never both. Words enter on beats, not at random.\\nDo not generate audio. I will mux the track with ffmpeg.\\n1920x1080, 60fps, single HTML file, every frame from t. Show me the layout plan per phrase before coding."},{"id":"ui-walkthrough","title":"App walkthrough from your real UI","format":"ui","duration":30,"aspect":"16:9","prompt":"Read the components in [path to UI code or screenshots] and make a 30-second walkthrough of [user flow].\\n\\nRebuild the screens in HTML with the real colours, fonts and copy. Animate a cursor through the flow: [step 1], [step 2], [step 3]. Zoom in on each detail that matters, then pull back.\\nPace: one action per 3 to 4 seconds, so a viewer can follow.\\n1920x1080, 60fps, render(t) deterministic, no fake features."},{"id":"world-flythrough","title":"3D world flythrough","format":"world","duration":20,"aspect":"16:9","prompt":"Build a 3D scene of [place or world] in Three.js and make a 20-second camera flythrough.\\n\\nShots: wide establishing shot, slow push into [main area], one moment of life ([what moves]), pull out to reveal everything.\\nEverything is procedural, no external models. Fixed random seed. Objects sit on the ground, never float.\\n1920x1080, 60fps. Expose render(t) that sets the camera and all animation from t. Screenshot four frames and check them before delivery."},{"id":"character-short","title":"Hand-drawn character short","format":"story","duration":15,"aspect":"16:9","prompt":"Make a 15-second animated short of [character] trying to [goal].\\n\\nStory: wants it, tries, fails in a funny way, surprise solution, payoff. Something happens in every shot.\\nLook: hand-painted brush strokes on paper texture, no plain vector shapes, no text on screen. Faces act, not just bodies.\\nTiming: list what the viewer must notice in each shot and give each moment enough frames to read.\\n24fps, 1920x1080, p5.js, every frame a function of t. Storyboard first."},{"id":"paper-explainer","title":"Research paper in 60 seconds","format":"explainer","duration":60,"aspect":"16:9","prompt":"Read this paper: [link or PDF]. Make a 60-second explainer for engineers who have not read it.\\n\\nCover: the problem, the key idea as one diagram, how it works in three steps, the main result with the real number, one limitation.\\nWrite the narration first, about 150 words, and time each scene to it.\\nStyle: clean whiteboard diagrams that build up, math only where it helps.\\n1920x1080, 30fps, deterministic render(t). Do not state any number that is not in the paper."},{"id":"repo-promo","title":"GitHub repo promo","format":"launch","duration":20,"aspect":"16:9","prompt":"Read this repository's README and code: [repo]. Make a 20-second promo video for it.\\n\\nShow: the one-line pitch, the install command typed into a terminal, the result it produces, the star count as [number]. Use a real terminal look and the project's own name and colours.\\nNo made-up features or testimonials.\\n1920x1080, 60fps, single HTML file with render(t), then write a Playwright + ffmpeg script that exports an MP4."},{"id":"loop-bg","title":"Seamless background loop","format":"showreel","duration":10,"aspect":"16:9","prompt":"Make a 10-second seamless loop to use as a website hero background.\\n\\nThe last frame must match the first exactly: drive all motion from sin and cos of (2*PI*t / 10).\\nCalm, slow, low contrast so text can sit on top. Colours: [palette].\\nGLSL fragment shader or Canvas, 1920x1080, 30fps, render(t) deterministic."},{"id":"changelog","title":"Changelog / release notes video","format":"ui","duration":30,"aspect":"16:9","prompt":"Turn these release notes into a 30-second video: [paste notes].\\n\\nPick the 3 changes a user would care about most. For each one show a before and after in the UI, 6 to 8 seconds each. Open with the version number, close with how to update.\\nRebuild UI in HTML with our colours [hex codes]. 1920x1080, 60fps, deterministic render(t)."}],"faqs":[{"q":"What is the best prompt for Opus 5.5 video?","a":"A short one with five things in it: what the viewer should understand, duration, aspect ratio, a style, and what to avoid. Then ask for a storyboard before code. Use the builder on this page to assemble one, or start from a template."},{"q":"How long should a video prompt be?","a":"The median creator prompt is about 35 words, and nearly half are under 200 characters. Long specs help for 3D scenes, games and anything with exact timing. For a first draft, short is fine."},{"q":"Do I need to tell Claude which library to use?","a":"Usually not. In the prompts we analysed, only 38% named a library, yet the results used Canvas, SVG, Three.js and shaders fluently. Name one when you need a specific look: Three.js for 3D, p5.brush for hand-painted."},{"q":"Why does my Claude video look generic?","a":"Usually the same handful of effects: particle bursts, glow, lens flares, bouncy easing, and text that repeats the picture. Ban them by name and give one concrete style reference instead of adjectives."},{"q":"How do I get the video synced to music?","a":"Give Claude the BPM and the start offset of the first beat. Ask for cuts and key hits on the beat grid, and for a storyboard laid out on that grid. Supply the track yourself and mux it in with ffmpeg."},{"q":"How do I iterate without breaking what works?","a":"One change per message and name what to keep: \\"Keep everything else, only change scene 2.\\" Review at half resolution and save the full quality render for the end."},{"q":"Can I use these prompts commercially?","a":"Yes. We wrote the templates on this page. Your output is subject to Anthropic's terms and to the licenses of any music, fonts or logos you put in."}]}`),Z=JSON.parse('{"groups":[{"id":"graphic","title":"Graphic & type","icon":"ph:text-t-bold"},{"id":"explain","title":"Explain & sell","icon":"ph:presentation-chart-bold"},{"id":"drawn","title":"Hand-made","icon":"ph:paint-brush-bold"},{"id":"retro","title":"Retro & era","icon":"ph:television-simple-bold"},{"id":"dimensional","title":"3D & worlds","icon":"ph:cube-bold"}],"list":[{"id":"swiss","name":"Swiss grid & kinetic type","group":"graphic","look":"A modular grid, one typeface, one signal colour. Type snaps into cells like a printing press.","useFor":["Brand identity","Event openers","Conference titles"],"stack":"Canvas 2D or SVG","palette":["#f5f2ea","#111111","#e63323"],"rules":["One easing curve for snaps, cubic-bezier(.7,0,.2,1). Linear only for lines being drawn.","Entrances are wipes or clip reveals, never fades. Deletions are hard cuts.","Exactly one element carries the signal colour per shot. That element is the subject.","Every position lands on a 12-column grid with 4% margins."],"avoid":"Overshoot, springs, drop shadows, more than one typeface, centred-everything layouts","prompt":"Style: Swiss International motion design. Off-white #f5f2ea, black #111, one signal red #e63323 used on a single element per shot. One grotesk typeface in two weights. A visible 12-column grid with 4% margins; every element snaps to it. Snaps use cubic-bezier(.7,0,.2,1), lines draw at linear speed. Entrances are wipes and clip reveals, never fades; exits are hard cuts on the beat. No overshoot, no shadows, no gradients."},{"id":"flat-vector","name":"Flat vector explainer","group":"explain","look":"Flat colour shapes and simple geometric characters with springy, confident movement.","useFor":["SaaS promos","Onboarding","Science explainers"],"stack":"SVG + GSAP","palette":["#fdf6ec","#2b2d42","#ff6b35","#4ecdc4","#ffd23f"],"rules":["Entrances overshoot with cubic-bezier(0.34,1.56,0.64,1) and settle within 12 frames.","Stagger groups by 2 to 4 frames, never all at once.","Transitions are carried by an element: a shape grows to fill the frame and becomes the next background.","Four to five flat colours, no gradients, no outlines thinner than 3px at 1080p."],"avoid":"Stock-illustration people with tiny heads, gradients, crossfades between scenes","prompt":"Style: flat vector explainer. Palette #fdf6ec background, #2b2d42 ink, accents #ff6b35, #4ecdc4, #ffd23f. Geometric shapes and simple characters built from circles and rounded rectangles, no gradients. Entrances overshoot with cubic-bezier(0.34,1.56,0.64,1) and settle within 12 frames, groups stagger by 3 frames. Scene changes are carried by a shape that grows to fill the frame and becomes the next background. No crossfades."},{"id":"morph","name":"Shape morph & liquid","group":"graphic","look":"One shape keeps turning into the next. The story is told by transformation, not cuts.","useFor":["Music videos","Brand stories","Transitions between topics"],"stack":"SVG path morphing, or WebGL metaballs for liquid","palette":["#0d1b2a","#f72585","#7209b7","#4cc9f0"],"rules":["There are no cuts. Every new idea grows out of the previous shape.","Each morph takes 18 to 30 frames and passes through a readable in-between shape.","Hold each finished shape at least 1 second so it reads.","Liquid joins use smooth-min blending, never a hard overlap."],"avoid":"Morphs that pass through a shapeless blob, constant motion with no holds","prompt":"Style: continuous shape morph. Dark #0d1b2a field, shapes in #f72585, #7209b7, #4cc9f0. No cuts: each idea grows out of the previous shape through a readable in-between form over 18 to 30 frames, then holds for at least 1 second. Liquid moments use metaball blending so drops merge smoothly. Camera stays still; the shapes do the moving."},{"id":"line-draw","name":"Single line & live drawing","group":"drawn","look":"One ink line draws itself, never lifts, and becomes the next picture. The camera follows the pen.","useFor":["Minimal ads","Luxury brands","Whiteboard explainers"],"stack":"SVG stroke-dashoffset or Canvas path sampling","palette":["#faf7f0","#1a1a1a","#c1121f"],"rules":["The line draws at a steady speed, linear easing, about 800px per second at 1080p.","The camera pans to keep the pen tip in the middle third of the frame.","One fill moment: the closed line floods with colour on a downbeat.","Constant stroke width, round caps."],"avoid":"Many lines drawing at once, fades in, text typed letter by letter","prompt":"Style: single continuous line drawing. Warm paper #faf7f0, ink #1a1a1a, one accent #c1121f. One line, round caps, constant 4px width, draws itself at a steady linear speed of about 800px/s and never lifts; each picture becomes the next by continuing the line. The camera pans to keep the pen tip in the middle third. One moment where a closed shape floods with the accent colour on a beat."},{"id":"dataviz","name":"Data story","group":"explain","look":"Real numbers drawn mark by mark, with one annotation that says why it matters.","useFor":["Reports","Data journalism","Investor updates"],"stack":"Canvas 2D or SVG + d3 scales","palette":["#fffdf7","#222222","#d62828","#457b9d"],"rules":["One reading per screen. Never show two charts at once.","Bars grow from the baseline in 20 frames with ease-out; counters roll to the exact value and stop.","Every number on screen comes from the data you were given.","Axis labels at least 28px at 1080p so they read on a phone."],"avoid":"3D charts, rainbow palettes, decorative gridlines, numbers that are not in the source","prompt":"Style: editorial data storytelling. Cream #fffdf7, ink #222, one highlight red #d62828 for the series that matters, muted blue #457b9d for the rest. One reading per screen. Bars and lines grow from the baseline over 20 frames with ease-out, counters roll to the exact value and stop dead. One handwritten-style annotation per chart says why the change matters. Labels at least 28px. Use only numbers from the data provided."},{"id":"isometric","name":"Isometric miniature world","group":"dimensional","look":"A tidy isometric diorama that builds itself, block by block, and opens up to show how things work.","useFor":["Architecture diagrams","Supply chains","App feature demos"],"stack":"Three.js orthographic camera, or Canvas with an iso projection","palette":["#eef2f3","#2d3142","#ef8354","#4f5d75","#bfc0c0"],"rules":["True isometric angles. The camera slides, it never rotates in perspective.","Objects drop in from 40px above with a small bounce, staggered by 3 frames.","Three tones per material: top light, left mid, right dark.","Things open to reveal their insides instead of cutting to a new scene."],"avoid":"Perspective cameras, realistic textures, labels floating without leader lines","prompt":"Style: isometric miniature world. Orthographic camera at true isometric angles; it slides but never rotates into perspective. Background #eef2f3, ink #2d3142, accent #ef8354, shades #4f5d75 and #bfc0c0. Every block has three flat tones: light top, mid left, dark right. Pieces drop in from 40px above with a small bounce, staggered by 3 frames. To explain a step, lift the roof off a building and show the process inside. Labels use thin leader lines."},{"id":"dark-keynote","name":"Dark tech keynote","group":"explain","look":"Near-black stage, hairline grid, one accent, light sweeping across a product, one giant number.","useFor":["Product launches","AI and SaaS","Feature reveals"],"stack":"Canvas 2D, or Three.js for a product model","palette":["#0a0a0a","#f5f5f5","#8b8b8b","#ff5a1f"],"rules":["Slow, long-tail easing, cubic-bezier(.16,1,.3,1), 30 to 45 frames per move.","One giant number per piece, 30% of frame height, counted up to its exact value.","Reveals come from light: a soft sweep passes and leaves the object lit.","The accent colour appears on one thing only."],"avoid":"Lens flares, neon glow, particle bursts, more than one accent colour","prompt":"Style: dark tech keynote. Near-black #0a0a0a stage with a faint hairline grid, white #f5f5f5 type, grey #8b8b8b secondary, one accent #ff5a1f on a single element. Slow long-tail easing cubic-bezier(.16,1,.3,1), 30 to 45 frames per move. Objects are revealed by a soft light sweep rather than fades. One giant number at 30% of frame height counts up to its exact value. No lens flares, no glow, no particles."},{"id":"screencast","name":"Living UI screencast","group":"explain","look":"Looks like a real screen recording, but every pixel is rebuilt in HTML, so the camera can zoom and the UI can act.","useFor":["Product tutorials","Feature launches","Changelogs"],"stack":"HTML + CSS + SVG, driven by a timeline seeked to t","palette":["#ffffff","#f3f4f6","#111827","#2563eb"],"rules":["Rebuild the real UI with real copy and colours. Never use screenshots.","The cursor moves on eased curves, 20 to 30 frames per move, and pauses 8 frames before each click.","Zoom to 1.6x on the detail that matters, then pull back.","One action every 3 to 4 seconds so the viewer can follow."],"avoid":"Fake features, cursor teleporting, lorem ipsum, zooming on nothing","prompt":"Style: living screencast. Rebuild the interface in HTML and CSS with its real copy, fonts and colours; no screenshots. A cursor moves on eased curves over 20 to 30 frames, pauses 8 frames, clicks with a small ripple. The camera zooms to 1.6x on each detail that matters, then pulls back. One action every 3 to 4 seconds. Do not show any feature that the product does not have."},{"id":"hud","name":"HUD & terminal","group":"retro","look":"Wireframes, lock-on brackets, rolling numbers and monospace glyph grids.","useFor":["Developer tools","Spec walkthroughs","Sci-fi and AI demos"],"stack":"Canvas 2D glyph grid, SVG overlays, optional Three.js wireframe","palette":["#050b0f","#38e8ff","#ffb000","#1d3540"],"rules":["All text is monospace and sits on a character grid.","Numbers roll through random glyphs for 6 to 10 frames before settling on the real value.","Brackets lock onto a target in 3 steps: wide, tighter, locked with a tick.","Two colours max on the dark field, plus dim grid lines."],"avoid":"Heavy glow and bloom, glitch tearing, unreadable tiny text","prompt":"Style: technical HUD. Dark #050b0f field, cyan #38e8ff primary, amber #ffb000 for warnings, dim #1d3540 grid. All type monospace on a character grid. Numbers scramble through glyphs for 6 to 10 frames then lock to the true value. Target brackets lock in three steps with a tick. Thin 1.5px lines, no bloom, no glitch tearing, every label readable at 1080p."},{"id":"painterly","name":"Watercolour & ink","group":"drawn","look":"Brush strokes paint themselves on textured paper. Washes bleed past the lines.","useFor":["Storytelling","Travel and nature","Cultural brands"],"stack":"Canvas brush engine or p5.js + p5.brush","palette":["#f4efe6","#2f3e46","#bc4749","#6a994e","#a7c4d2"],"rules":["Everything is painted with strokes. No plain vector shapes.","Washes reveal over 15 to 25 frames and bleed 4 to 8px past the ink line.","Paper texture is always visible; pure white and pure black never appear.","Linework re-randomises 12 times a second from a seed, so it lives without flickering."],"avoid":"Perfect geometric shapes, digital gradients, text labels on everything","prompt":"Style: watercolour and ink on paper. Warm paper #f4efe6 with visible grain, ink #2f3e46, washes in #bc4749, #6a994e, #a7c4d2. Paint every element with brush strokes, never plain shapes. Washes spread over 15 to 25 frames and bleed slightly past the ink. Linework wobbles on twos (re-seeded 12 times per second from a fixed seed). No pure white, no pure black, very little text."},{"id":"print","name":"Risograph & halftone print","group":"drawn","look":"Two or three spot inks overprinted on warm paper, halftone dots, plates slightly out of register.","useFor":["Indie brands","Zines","Event posters"],"stack":"Canvas 2D or a WebGL print shader","palette":["#f3ede2","#ff48b0","#0078bf","#ffe800"],"rules":["Two or three inks only. Where inks overlap they multiply.","Each plate is offset 2 to 4px from the others and stays there.","Tones are halftone dots, no smooth gradients.","Motion steps at 12fps for a printed, hand-pulled feel."],"avoid":"A fourth ink, perfect registration, glossy highlights","prompt":"Style: risograph print. Warm paper #f3ede2. Two spot inks, fluorescent pink #ff48b0 and blue #0078bf (optional yellow #ffe800), overprinted with multiply blending. Each ink plate is misregistered 2 to 4px and stays offset. All tones are halftone dots, never smooth gradients. Animation steps at 12fps while the camera stays smooth."},{"id":"papercut","name":"Paper cut-out & collage","group":"drawn","look":"Layered card and photo cut-outs with white scissor edges, moving in stop-motion steps.","useFor":["Music and fashion","Kids stories","Editorial pieces"],"stack":"Canvas or DOM layers with drop shadows between them","palette":["#e9e3d5","#1b1b1b","#e76f51","#2a9d8f","#f4a261"],"rules":["Every piece has a white or cut edge and a small hard shadow on the layer below.","Pieces move in stop-motion steps at 12fps; the camera can move at 24.","Depth comes from 3 to 6 parallax layers.","Joints pivot like split pins, they do not bend."],"avoid":"Soft blurred shadows, smooth 60fps character motion, vector-perfect edges","prompt":"Style: paper cut-out collage. Card colours #e9e3d5, #e76f51, #2a9d8f, #f4a261 with black #1b1b1b details. Every piece has a slightly rough white cut edge and a small hard shadow on the layer below. Characters move in stop-motion steps at 12fps with split-pin joints; the camera drifts smoothly across 3 to 6 parallax layers."},{"id":"cel","name":"Hand-drawn line boil","group":"drawn","look":"Cartoon linework that wiggles every two frames, smears on fast moves, and looks drawn by hand.","useFor":["Character shorts","Playful brands","Social clips"],"stack":"Canvas 2D variable-width strokes with 3 jitter variants","palette":["#fffaf0","#1c1c1c","#ff595e","#1982c4","#ffca3a"],"rules":["Animate on twos: the drawing changes every 2 frames at 24fps.","Cycle 3 jitter variants of every line so it boils without strobing.","Fast moves get a smear frame instead of motion blur.","Anticipation before every big action: a small move the other way for 4 to 6 frames."],"avoid":"Tweened vector motion at 60fps, perfect circles, text standing in for acting","prompt":"Style: hand-drawn cartoon with line boil. Off-white #fffaf0, ink #1c1c1c, flat fills #ff595e, #1982c4, #ffca3a. 24fps animated on twos. Every line has 3 jitter variants cycled so it boils. Fast moves use a smear frame, every big action gets 4 to 6 frames of anticipation, faces act. Variable-width ink lines, no perfect geometric shapes, almost no text."},{"id":"pixel","name":"Pixel art & retro game","group":"retro","look":"Big pixels, a limited palette, sprite cycles and chiptune timing.","useFor":["Game trailers","Nostalgia marketing","Year-in-review"],"stack":"Canvas at 320x180, scaled up with nearest-neighbour","palette":["#1a1c2c","#5d275d","#b13e53","#ef7d57","#ffcd75","#a7f070","#38b764","#41a6f6"],"rules":["Draw at 320x180 and scale by 6 with image smoothing off. Never draw at full resolution.","One fixed palette of 16 to 32 colours. Shading uses dithering, not blending.","Sprites animate at 8 to 12fps; the camera snaps to whole pixels.","Text uses a pixel font and types out in dialogue boxes."],"avoid":"Mixed pixel sizes, blurry scaling, anti-aliased edges, smooth sub-pixel motion","prompt":"Style: 16-bit pixel art. Render to a 320x180 canvas and scale 6x with imageSmoothingEnabled = false. Use one fixed palette (#1a1c2c, #5d275d, #b13e53, #ef7d57, #ffcd75, #a7f070, #38b764, #41a6f6 plus greys). Shading by dithering only. Sprites animate at 8 to 12fps, camera moves in whole pixels, dialogue in a pixel font that types out in a bordered box."},{"id":"tape","name":"VHS, film & CRT eras","group":"retro","look":"The texture of old media: grain, gate weave, scanlines, colour bleed, tracking lines.","useFor":["Music videos","Throwback campaigns","Mystery teasers"],"stack":"Canvas or Three.js scene plus a WebGL post-processing pass","palette":["#120f1d","#ff3fa4","#00e5ff","#ffd166"],"rules":["Pick one era and commit: 1920s film, 1980s VHS, or 1990s camcorder.","Texture is seeded per frame index, so grain changes every frame but renders the same every time.","Gate weave of about 1px and brightness flicker of about 5% for film. Chroma shift of 2 to 3px for tape.","Keep it legible: the effect sits on top of a clear composition, it is not the composition."],"avoid":"Stacking every retro effect at once, glitch tearing over important text","prompt":"Style: 1980s VHS tape. Scene in deep #120f1d with neon accents #ff3fa4, #00e5ff and warm #ffd166. Post pass: scanlines, 2 to 3px chroma shift, slight tape noise and an occasional tracking line, all seeded by frame index so the render is deterministic. A chrome title moment. Keep the composition clear underneath; the tape texture never covers key text."},{"id":"toy3d","name":"Toy & material 3D","group":"dimensional","look":"Soft studio-lit 3D objects that look like toys, clay or candy, with shallow depth of field.","useFor":["Product films","Brand idents","Playful explainers"],"stack":"Three.js with physical materials and an environment map","palette":["#f6e6e4","#ff8fab","#7bdff2","#b2f7ef","#fcbf49"],"rules":["Soft studio light from one big key and a fill. Matte or soft-gloss materials.","Shallow depth of field keeps attention on one object.","Objects arrive with weight: fast in, 2 small settles, no floating.","Fixed random seed for every procedural shape."],"avoid":"Chrome everything, hard black shadows, objects floating with no contact shadow","prompt":"Style: toy-like 3D. Three.js, soft studio lighting with one large key and a fill, pastel background #f6e6e4, matte and soft-gloss materials in #ff8fab, #7bdff2, #b2f7ef, #fcbf49. Shallow depth of field on the hero object. Objects land with weight and two small settles, always with a contact shadow. Fixed seeds for any procedural geometry."},{"id":"social","name":"Vertical social captions","group":"graphic","look":"Bold captions pop on every phrase, built for sound-off viewing in a 9:16 frame.","useFor":["Reels, Shorts, TikTok","Founder clips","Tips and listicles"],"stack":"HTML + CSS text, Canvas for backgrounds","palette":["#000000","#ffffff","#ffe600","#ff2e63"],"rules":["1080x1920. Keep everything inside the middle 80% so platform buttons do not cover it.","Captions of 1 to 4 words, each popping in on its spoken beat with a 6 frame scale overshoot.","The first second must hook with the sound off.","Highlight one word per caption in the accent colour."],"avoid":"Long sentences on screen, text in the bottom 15%, small type","prompt":"Style: vertical social captions. 1080x1920, all content inside the middle 80% of the frame. Black #000 and white #fff with yellow #ffe600 for the one highlighted word per caption and pink #ff2e63 for emphasis stamps. Captions are 1 to 4 words, chunky with a thick outline, popping in on each beat with a 6 frame scale overshoot. The first second must work with the sound off."}],"anatomy":[{"part":"Medium in one clause","example":"Risograph print, two spot inks on warm paper."},{"part":"Palette with hex codes","example":"Off-white #f5f2ea, black #111, one red #e63323."},{"part":"Colour logic","example":"Only one element carries the signal colour per shot."},{"part":"Easing as a number","example":"Snaps use cubic-bezier(.7,0,.2,1). Not \\"smooth\\"."},{"part":"Timing as frames","example":"Groups stagger by 3 frames. Morphs take 18 to 30."},{"part":"How shots connect","example":"Wipes, never fades. A shape grows into the next scene."},{"part":"Texture parameters","example":"Plates misregistered 2 to 4px. Grain seeded per frame."},{"part":"Frame rate as a style choice","example":"12fps stepping for paper, 24 on twos for drawn, 60 for UI."},{"part":"An avoid list","example":"No overshoot, no shadows, no gradients."}],"skillFile":"---\\nname: motion-graphics\\ndescription: Make motion graphics and short videos as code (Canvas, SVG, Three.js) and render them to MP4 frame by frame. Use when the user asks for a video, animation, motion graphic, logo reveal, launch spot, explainer, lyric video or social clip.\\n---\\n\\n# Motion graphics as code\\n\\nYou make videos by writing code that draws every frame, then rendering it frame by frame to MP4.\\nThere is no video model. The quality comes from planning, timing and review.\\n\\n## 1. Ask once, then work\\n\\nIf any of these are missing, ask for all of them in one message, then do not ask again:\\n- What should the viewer understand or feel by the end?\\n- Duration, aspect ratio (16:9, 9:16, 1:1, 4:5) and where it will play.\\n- Real facts, copy, brand colours, logo SVG, product UI or data. Never invent features, numbers or quotes.\\n- Audio: none, a track the user supplies (get the BPM), generated music, or voiceover.\\n- Style: one named style. If none is given, pick one and say why in one line.\\n\\n## 2. Storyboard before code\\n\\nWrite a shot list and show it to the user before writing animation code:\\n- One row per shot: start time, end time, what is on screen, what the viewer must read, the transition out.\\n- List every \\"read\\" (a thing the viewer must notice) and give each its own slot. Fast actions, slow meanings.\\n- A hook inside the first second. Something happens in every shot. Hold the final frame 0.8 to 1.2 s.\\n- If there is music, put cuts and key hits on the beat grid. Not every beat gets a hit.\\n\\n## 3. Build rules\\n\\n- One `scene.html` that draws any moment on request. Expose `window.renderAt(t)` and also run a normal\\n  requestAnimationFrame preview loop that reads `performance.now()`.\\n- Every frame is a pure function of time. No counters that increment per frame, no unseeded `Math.random()`,\\n  no physics integrated step by step, no CSS transitions triggered by timers. Seed all randomness.\\n- `await document.fonts.ready` before the first frame. Load fonts locally or from a stable CDN.\\n- Write the style as numbers: hex colours, cubic-bezier curves, frame counts for staggers, grid margins.\\n- Keep text inside a 5% safe margin (middle 80% for vertical social video).\\n- Default avoid list unless the style asks for it: particle bursts, lens flares, neon glow, RGB split, glitch,\\n  bouncy easing on everything, decorative gradients, text that repeats what the picture shows.\\n\\n## 4. Review before the full render\\n\\n- Render a contact sheet: one frame per second (or per beat) tiled into one PNG. Open it and look.\\n- Check for: overlapping or clipped text, text on screen too short to read (about 0.3 s per word, minimum 1 s),\\n  dead time, fallback fonts, elements too small to see at phone size, black frames.\\n- Fix what you find, then render a half-resolution draft, then the final.\\n\\n## 5. Render\\n\\nUse a virtual clock: replace `performance.now`, `Date.now` and `requestAnimationFrame`, advance time by exactly\\n1/fps per frame, screenshot each frame, pipe the PNGs into ffmpeg. Reference script:\\nhttps://awesomeclaude.ai/claude-video-render.mjs\\n\\n```bash\\nnode claude-video-render.mjs scene.html out.mp4 15 60 1920 1080\\nffmpeg -i out.mp4 -i track.mp3 -c:v copy -c:a aac -b:a 192k -shortest final.mp4\\n```\\n\\nNever record audio from the browser. Mux the track with ffmpeg so sync is exact.\\n\\n## 6. Report\\n\\nDeliver the MP4 path, the storyboard as built, the style rules you followed, and the two weakest moments\\nwith how you would fix them in another round.\\n\\n---\\nMade by awesomeclaude.ai. Styles with copy-paste rules: https://awesomeclaude.ai/claude-motion-graphics\\n","faqs":[{"q":"Can Claude make motion graphics?","a":"Yes. Claude Opus 5.5 writes motion graphics as code, usually Canvas, SVG with GSAP, or Three.js, and a headless browser renders them to MP4. Motion graphics are by far the most common kind of Claude video: more than half of the creator prompts we analysed asked for one."},{"q":"What is a Claude motion graphics skill?","a":"A SKILL.md file that teaches Claude Code your style rules, render setup and review steps, so you can ask for \\"a 15s launch video in the swiss style\\" without re-explaining the look. Download ours from this page and drop it into .claude/skills/motion-graphics/."},{"q":"How do I keep a consistent style across videos?","a":"Write the style as numbers, not adjectives: hex colours, easing curves, frame counts, grid margins. Put it in a skill or a STYLE.md file in the project, and ask Claude to check its contact sheet against those rules before rendering."},{"q":"Which style is best for a product launch?","a":"Dark tech keynote for AI and developer products, living UI screencast when the interface is the product, and flat vector when you need to explain a concept to a non-technical audience."},{"q":"Why do all AI motion graphics look the same?","a":"Because the same defaults keep showing up: glow, particle bursts, lens flares, bouncy easing on everything, gradient backgrounds. A specific style with an avoid list and testable rules gets you out of that look fast."},{"q":"Can I use these style prompts commercially?","a":"Yes. We wrote them and you can paste them into any prompt or skill. Check the licenses of any fonts, music or images you add."}]}'),se={metadata:Y,hub:K,prompts:J,styles:Z};export{ae as _,oe as a,se as d};
